/* @lc app=leetcode id=4073 lang=kotlin */ class Solution { fun countGoodStrings(n: Long): Int = java.lang.Long.toBinaryString(n).fold(listOf(0L, 1L)) { (a, b), bit -> (a * ((2 * b - a + 1_000_000_007L) % 1_000_000_007L) % 1_000_000_007L).let { c -> ((a * a + b * b) % 1_000_000_007L).let { d -> if (bit == '1') listOf(d, (c + d) % 1_000_000_007L) else listOf(c, d) } } }.let { (2 * it[0] % 1_000_000_007L).toInt() } }